        assert_eq!(summarize_hours(&entries), "hr:5\nops:5\nsales:4\nlegal:1");
    }

    #[test]
    fn returns_empty_string_when_nothing_reportable() {
        let entries = [("", 2), ("sales", 0), ("", 0)];
        assert_eq!(summarize_hours(&entries), "");
    }
}

